import java.util.*;
import java.io.*;
import java.math.*;

public class Main {
    static long pr = 998244353;
    static BigInteger p = new BigInteger("998244353");
    static void err() {
        System.out.println(-1);
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int t = 1;
        // t = Integer.parseInt(st.nextToken());
        while (t-- > 0) {
            st = new StringTokenizer(br.readLine());
            long n = Long.parseLong(st.nextToken());
            long m = Long.parseLong(st.nextToken());
            st = new StringTokenizer(br.readLine());
            long l = Long.parseLong(st.nextToken());
            long r = Long.parseLong(st.nextToken());
            long k = r - l;
            long even = k / 2 + 1;
            long odd = (k + 1) / 2;
            if ((n * m) % 2 == 1) {
                BigInteger res = BigInteger.valueOf(k + 1).modPow(BigInteger.valueOf(n * m), p);
                out.println(res);
            } else {
                BigInteger temp1 = BigInteger.valueOf(even + odd).modPow(BigInteger.valueOf(n * m), p);
                BigInteger temp2 = BigInteger.valueOf(even - odd).modPow(BigInteger.valueOf(n * m), p);
                BigInteger sum = temp1.add(temp2);
                BigInteger half = BigInteger.valueOf(pr + 1).divide(BigInteger.valueOf(2));
                BigInteger result = sum.multiply(half).mod(BigInteger.valueOf(pr));
                out.println(result);
            }
        }
        out.flush();
    }
}
